/* WL Scheduler — offline cache (generated by tools/webapp.py).
   V24.32: the page itself is NETWORK FIRST (asks the server whether index.html changed — a small 304 when it did not —
   and falls back to the saved copy when offline or after 4 s), so a new version shows on the next opening, not the one after.
   Icons / manifest stay cache first. "wl-version?" from the page → reads version.json (never cached) and answers, so the
   page can say "มีเวอร์ชันใหม่" without the page itself being allowed to connect anywhere (its CSP stays as it is). */
const CACHE='school-planner-71b3bab1daeb',FILES=["./", "index.html", "manifest.webmanifest", "icon-180.png", "icon-192.png", "icon-512.png", "icon-maskable-512.png"],PAGE=['./','index.html'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(f=>new Request(f,{cache:'reload'})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{
  const u=new URL(e.request.url);
  if(e.request.method!=='GET'||u.origin!==location.origin||/version\.json$/.test(u.pathname))return;
  const page=e.request.mode==='navigate'||/\/(index\.html)?$/.test(u.pathname);
  if(page){e.respondWith(caches.open(CACHE).then(c=>{
    const saved=()=>c.match(e.request,{ignoreSearch:true}).then(h=>h||c.match('index.html'));
    const net=fetch(new Request(u.origin+u.pathname,{cache:'no-cache',credentials:'same-origin'})).then(r=>{if(r&&r.ok){const k=r.clone();c.put('index.html',k.clone());c.put('./',k)}return r});
    const late=new Promise(res=>setTimeout(()=>res(null),4000));
    return Promise.race([net.catch(()=>null),late]).then(r=>r&&r.ok?r:saved().then(h=>h||net));
  }));return}
  e.respondWith(caches.open(CACHE).then(c=>c.match(e.request,{ignoreSearch:true}).then(hit=>{
    const net=fetch(e.request).then(r=>{if(r&&r.ok)c.put(e.request,r.clone());return r}).catch(()=>hit);
    return hit||net})));
});
self.addEventListener('message',e=>{if(e.data!=='wl-version?'||!e.source)return;
  e.waitUntil(fetch('version.json?t='+Date.now(),{cache:'no-store'}).then(r=>r.json()).then(j=>e.source.postMessage({wlVersion:j.ver,label:j.label})).catch(()=>{}))});
